import { defineFeature } from "../core/composition/define-feature.js";
import { loadVideoSegments } from "../behaviors/dom/load-segments.js";
import { SVTA_NO_SUPPORTED_VIDEO_TRACK } from "../media/errors.js";
import { excludeUnplayableTracks } from "../playback/primitives/selection-rules.js";
import { preferHighestResolution, screenResolutionCap, selectVideoTrack } from "../behaviors/select-tracks.js";
import { reportAbsentTrackType } from "../behaviors/collect-errors.js";
import { canPlayTrack } from "../media/dom/capabilities.js";
import { setupVideoBufferActors } from "../behaviors/dom/setup-buffer-actors.js";
import { resolveVideoTrack } from "../behaviors/resolve-track.js";
import { reportUnsupportedTrackConditions } from "../playback/primitives/report-track-conditions.js";
import { trackScreenResolution } from "../behaviors/dom/track-screen-resolution.js";
//#region src/playback/features/background-video.ts
const videoConstraints = [excludeUnplayableTracks, reportAbsentTrackType(SVTA_NO_SUPPORTED_VIDEO_TRACK)];
const videoRules = [screenResolutionCap, preferHighestResolution];
/** The behaviors the feature composes, in setup order. */
const behaviors = [
	selectVideoTrack,
	resolveVideoTrack,
	setupVideoBufferActors,
	loadVideoSegments,
	trackScreenResolution
];
/** The config defaults the feature contributes. */
const defaultConfig = {
	videoConstraints,
	videoRules,
	canPlayTrack,
	reportUnsupportedTrackConditions
};
/** The state values the feature seeds. */
const initialState = {};
/**
* Plays one video rendition for the whole session: the largest that fits the screen, picked once rather than adapted to
* bandwidth. For ambient, hero, and GIF-replacement video. Reports when no rendition is playable.
*
* Requires, from this or other features:
*
* - A writer of `context.mediaSource`, such as `mediaSourceFeature`; nothing loads without one.
* - A writer of `state.currentTime`, such as `currentTimeFeature`; without one, loading stops after the first window.
* - A writer of `state.loadActivated`, such as `initialLoadFeature`, or a seeded `loadActivated: true`; without one, only
*   init segments load.
*/
const backgroundVideoFeature = defineFeature({
	behaviors,
	defaultConfig,
	initialState
});
//#endregion
export { backgroundVideoFeature, behaviors, defaultConfig, initialState };
